let categoriaActual = null;
let marcaActual = null;
let perfumeSeleccionado = null;
let cantidadSeleccionada = 1;
let carrito = [];

const $ = (selector) => document.querySelector(selector);

function formatearPrecio(precio) {
  return precio.toLocaleString("es-CO");
}

function escaparHTML(texto) {
  return String(texto)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function crearTarjetaProducto(nombre, precio, marca, imagen) {
  const tarjeta = document.createElement("article");

  tarjeta.className = "producto";
  tarjeta.tabIndex = 0;
  tarjeta.setAttribute("role", "button");
  tarjeta.setAttribute(
    "aria-label",
    `Ver ${nombre}`
  );

  tarjeta.innerHTML = `
    <div class="imagen-producto">
      <img
        src="${escaparHTML(imagen)}"
        alt="${escaparHTML(nombre)} de ${escaparHTML(marca)}"
        loading="lazy"
      >
    </div>

    <div class="producto-info">
      <div class="producto-marca">
        ${escaparHTML(marca)}
      </div>

      <h3 class="producto-nombre">
        ${escaparHTML(nombre)}
      </h3>

      <div class="producto-precio">
        $${formatearPrecio(precio)}
      </div>
    </div>
  `;

  const abrir = () => {
    mostrarDetalle(
      nombre,
      precio,
      marca,
      imagen
    );
  };

  tarjeta.addEventListener(
    "click",
    abrir
  );

  tarjeta.addEventListener(
    "keydown",
    (evento) => {
      if (
        evento.key === "Enter" ||
        evento.key === " "
      ) {
        evento.preventDefault();
        abrir();
      }
    }
  );

  return tarjeta;
}

function mostrarCategoria(categoria) {
  categoriaActual = categoria;
  marcaActual = null;
  perfumeSeleccionado = null;
  cantidadSeleccionada = 1;

  document
    .querySelectorAll(".categoria-card")
    .forEach((boton) => {
      boton.classList.toggle(
        "activa",
        boton.dataset.categoria === categoria
      );
    });

  $("#productos").innerHTML = `
    <div class="mensaje-vacio">
      Selecciona una marca para ver sus fragancias disponibles.
    </div>
  `;

  const detalle = $("#detalle-perfume");

  detalle.classList.remove("detalle-visible");
  detalle.classList.add("detalle-oculto");

  const marcas = Object.keys(
    catalogo[categoria] || {}
  );

  const contenedor = $("#marcas-container");
  contenedor.innerHTML = "";

  if (!marcas.length) {
    contenedor.innerHTML = `
      <div class="mensaje-vacio">
        No hay marcas disponibles para esta categoría.
      </div>
    `;
  } else {
    marcas.forEach((marca) => {
      const boton = document.createElement("button");

      boton.type = "button";
      boton.className = "marca-boton";
      boton.textContent = marca;

      boton.addEventListener(
        "click",
        () => {
          document
            .querySelectorAll(".marca-boton")
            .forEach((elemento) => {
              elemento.classList.remove("activa");
            });

          boton.classList.add("activa");
          mostrarCatalogo(marca);
        }
      );

      contenedor.appendChild(boton);
    });
  }

  mostrarRecomendaciones(categoria);

  $("#marcas").scrollIntoView({
    behavior: "smooth",
    block: "start"
  });
}

function mostrarCatalogo(marca) {
  if (
    !categoriaActual ||
    !catalogo[categoriaActual]?.[marca]
  ) {
    return;
  }

  marcaActual = marca;

  const productos =
    catalogo[categoriaActual][marca];

  document
    .querySelectorAll(".marca-boton")
    .forEach((boton) => {
      boton.classList.toggle(
        "activa",
        boton.textContent === marca
      );
    });

  const contenedor = $("#productos");
  contenedor.innerHTML = "";

  if (!productos.length) {
    contenedor.innerHTML = `
      <div class="mensaje-vacio">
        No hay fragancias disponibles para esta marca.
      </div>
    `;
    return;
  }

  productos.forEach(
    ([nombre, precio, imagen]) => {
      contenedor.appendChild(
        crearTarjetaProducto(
          nombre,
          precio,
          marca,
          imagen
        )
      );
    }
  );

  $("#productos-seccion").scrollIntoView({
    behavior: "smooth",
    block: "start"
  });
}

function normalizarTexto(texto) {
  return String(texto)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function obtenerTodosLosProductos() {
  const productos = [];

  Object.entries(catalogo).forEach(
    ([categoria, marcas]) => {

      Object.entries(marcas).forEach(
        ([marca, listaProductos]) => {

          listaProductos.forEach(
            ([nombre, precio, imagen]) => {

              productos.push({
                nombre,
                precio,
                imagen,
                marca,
                categoria
              });

            }
          );

        }
      );

    }
  );

  return productos;
}

function cargarMarcasFiltro() {
  const selector = $("#filtro-marca");

  if (!selector) {
    return;
  }

  const marcas = new Set();

  Object.values(catalogo).forEach(
    (marcasCategoria) => {

      Object.keys(marcasCategoria).forEach(
        (marca) => marcas.add(marca)
      );

    }
  );

  const marcasOrdenadas =
    [...marcas].sort(
      (a, b) => a.localeCompare(b, "es")
    );

  selector.innerHTML =
    `<option value="">Todas las marcas</option>`;

  marcasOrdenadas.forEach(
    (marca) => {

      const opcion =
        document.createElement("option");

      opcion.value = marca;
      opcion.textContent = marca;

      selector.appendChild(opcion);

    }
  );
}

function mostrarProductosFiltrados() {

  const precioMinimo =
    Number($("#precio-minimo")?.value) || 0;

  const valorPrecioMaximo =
    $("#precio-maximo")?.value || "";

  const precioMaximo =
    valorPrecioMaximo === ""
      ? Infinity
      : Number(valorPrecioMaximo);

  const categoria =
    $("#filtro-categoria")?.value || "";

  const marca =
    $("#filtro-marca")?.value || "";

  const nombreBuscado =
    normalizarTexto(
      $("#filtro-nombre")?.value || ""
    );

  const contenedor =
    $("#productos");

  if (!contenedor) {
    return;
  }

  if (precioMinimo > precioMaximo) {

    contenedor.innerHTML = `
      <div class="mensaje-vacio">
        El precio mínimo no puede ser mayor
        que el precio máximo.
      </div>
    `;

    return;
  }

  const productos =
    obtenerTodosLosProductos().filter(
      (producto) => {

        const cumplePrecioMinimo =
          producto.precio >= precioMinimo;

        const cumplePrecioMaximo =
          producto.precio <= precioMaximo;

        const cumpleCategoria =
          !categoria ||
          producto.categoria === categoria;

        const cumpleMarca =
          !marca ||
          producto.marca === marca;

        const cumpleNombre =
          !nombreBuscado ||
          normalizarTexto(
            producto.nombre
          ).includes(nombreBuscado);

        return (
          cumplePrecioMinimo &&
          cumplePrecioMaximo &&
          cumpleCategoria &&
          cumpleMarca &&
          cumpleNombre
        );

      }
    );

  contenedor.innerHTML = "";

  if (!productos.length) {

    contenedor.innerHTML = `
      <div class="mensaje-vacio">
        No encontramos fragancias que
        coincidan con estos filtros.
      </div>
    `;

    return;
  }

  productos.forEach(
    ({
      nombre,
      precio,
      marca,
      imagen
    }) => {

      contenedor.appendChild(
        crearTarjetaProducto(
          nombre,
          precio,
          marca,
          imagen
        )
      );

    }
  );

  $("#productos-seccion").scrollIntoView({
    behavior: "smooth",
    block: "start"
  });
}

function cerrarPanelFiltros() {

  const boton =
    $("#abrir-filtros");

  const panel =
    $("#panel-filtros");

  if (!boton || !panel) {
    return;
  }

  panel.classList.remove("abierto");

  boton.setAttribute(
    "aria-expanded",
    "false"
  );

  panel.setAttribute(
    "aria-hidden",
    "true"
  );
}

function limpiarFiltros() {

  const precioMinimo =
    $("#precio-minimo");

  const precioMaximo =
    $("#precio-maximo");

  const categoria =
    $("#filtro-categoria");

  const marca =
    $("#filtro-marca");

  const nombre =
    $("#filtro-nombre");

  if (precioMinimo) {
    precioMinimo.value = "";
  }

  if (precioMaximo) {
    precioMaximo.value = "";
  }

  if (categoria) {
    categoria.value = "";
  }

  if (marca) {
    marca.value = "";
  }

  if (nombre) {
    nombre.value = "";
  }

  cerrarPanelFiltros();

  if (
    categoriaActual &&
    marcaActual
  ) {

    mostrarCatalogo(
      marcaActual
    );

  } else {

    $("#productos").innerHTML = `
      <div class="mensaje-vacio">
        Selecciona una marca para ver sus
        fragancias disponibles.
      </div>
    `;

  }
}

function inicializarFiltros() {

  cargarMarcasFiltro();

  const botonAbrir =
    $("#abrir-filtros");

  const panel =
    $("#panel-filtros");

  const botonAplicar =
    $("#aplicar-filtros");

  const botonLimpiar =
    $("#limpiar-filtros");

  if (
    botonAbrir &&
    panel
  ) {

    botonAbrir.addEventListener(
      "click",
      (evento) => {

        evento.stopPropagation();

        const abierto =
          panel.classList.toggle(
            "abierto"
          );

        botonAbrir.setAttribute(
          "aria-expanded",
          String(abierto)
        );

        panel.setAttribute(
          "aria-hidden",
          String(!abierto)
        );

      }
    );

    panel.addEventListener(
      "click",
      (evento) =>
        evento.stopPropagation()
    );

    document.addEventListener(
      "click",
      () =>
        cerrarPanelFiltros()
    );
  }

  if (botonAplicar) {

    botonAplicar.addEventListener(
      "click",
      () => {

        mostrarProductosFiltrados();

        cerrarPanelFiltros();

      }
    );

  }

  if (botonLimpiar) {

    botonLimpiar.addEventListener(
      "click",
      limpiarFiltros
    );

  }
}

function encontrarCategoriaProducto(
  nombre,
  marca
) {

  for (
    const [categoria, marcas]
    of Object.entries(catalogo)
  ) {

    const productos =
      marcas[marca] || [];

    if (
      productos.some(
        ([nombreProducto]) =>
          nombreProducto === nombre
      )
    ) {

      return categoria;

    }

  }

  return null;
}

function mostrarDetalle(
  nombre,
  precio,
  marca,
  imagen
) {

  if (!categoriaActual) {

    categoriaActual =
      encontrarCategoriaProducto(
        nombre,
        marca
      );

  }

  perfumeSeleccionado = {
    nombre,
    precio,
    marca,
    imagen
  };

  cantidadSeleccionada =
    obtenerCantidadCarrito(
      nombre,
      marca
    ) || 1;

  const detalle =
    $("#detalle-perfume");

  detalle.classList.remove(
    "detalle-oculto"
  );

  detalle.classList.add(
    "detalle-visible"
  );

  $("#detalle-contenido").innerHTML = `
    <div class="detalle-imagen">
      <img
        src="${escaparHTML(imagen)}"
        alt="${escaparHTML(nombre)} de ${escaparHTML(marca)}"
      >
    </div>

    <div class="detalle-info">

      <div class="producto-marca">
        ${escaparHTML(marca)}
      </div>

      <h2>
        ${escaparHTML(nombre)}
      </h2>

      <div class="detalle-precio">
        $${formatearPrecio(precio)}
      </div>

      <p>
        Selecciona la cantidad que deseas
        añadir al carrito.
      </p>

      <div
        class="controles-cantidad"
        aria-label="Cantidad"
      >

        <button
          type="button"
          id="menos-detalle"
          aria-label="Disminuir cantidad"
        >
          −
        </button>

        <span id="cantidad-detalle">
          ${cantidadSeleccionada}
        </span>

        <button
          type="button"
          id="mas-detalle"
          aria-label="Aumentar cantidad"
        >
          +
        </button>

      </div>

      <br>

      <button
        type="button"
        id="agregar-detalle"
        class="boton boton-agregar"
      >
        🛒 Añadir al carrito
      </button>

    </div>
  `;

  $("#menos-detalle")
    .addEventListener(
      "click",
      () =>
        cambiarCantidadDetalle(-1)
    );

  $("#mas-detalle")
    .addEventListener(
      "click",
      () =>
        cambiarCantidadDetalle(1)
    );

  $("#agregar-detalle")
    .addEventListener(
      "click",
      () => {

        agregarCantidadAlCarrito(
          perfumeSeleccionado,
          cantidadSeleccionada
        );

        actualizarCarrito();

      }
    );

  mostrarRecomendacionesSimilares(
    nombre,
    marca
  );

  detalle.scrollIntoView({
    behavior: "smooth",
    block: "start"
  });
}

function cambiarCantidadDetalle(
  cambio
) {

  cantidadSeleccionada =
    Math.max(
      1,
      cantidadSeleccionada + cambio
    );

  $("#cantidad-detalle")
    .textContent =
    cantidadSeleccionada;
}

function agregarCantidadAlCarrito(
  producto,
  cantidad
) {

  const existente =
    carrito.find(
      (item) =>
        item.nombre === producto.nombre &&
        item.marca === producto.marca
    );

  if (existente) {

    existente.cantidad =
      cantidad;

  } else {

    carrito.push({
      ...producto,
      cantidad
    });

  }
}

function obtenerCantidadCarrito(
  nombre,
  marca
) {

  const item =
    carrito.find(
      (producto) =>
        producto.nombre === nombre &&
        producto.marca === marca
    );

  return item
    ? item.cantidad
    : 0;
}

function mostrarRecomendacionesSimilares(
  nombreActual,
  marca
) {

  const contenedor =
    $("#recomendaciones-container");

  const productos =
    catalogo[categoriaActual]?.[marca] || [];

  const similares =
    productos
      .filter(
        ([nombre]) =>
          nombre !== nombreActual
      )
      .slice(0, 4);

  contenedor.innerHTML = "";

  similares.forEach(
    ([nombre, precio, imagen]) => {

      contenedor.appendChild(
        crearTarjetaProducto(
          nombre,
          precio,
          marca,
          imagen
        )
      );

    }
  );
}

function mostrarRecomendaciones(
  categoria = null
) {

  const todos = [];

  const categorias =
    categoria
      ? [
          [
            categoria,
            catalogo[categoria]
          ]
        ]
      : Object.entries(catalogo);

  categorias.forEach(
    ([categoriaNombre, marcas]) => {

      Object.entries(marcas).forEach(
        ([marca, productos]) => {

          productos.forEach(
            ([nombre, precio, imagen]) => {

              todos.push({
                nombre,
                precio,
                marca,
                imagen,
                categoria:
                  categoriaNombre
              });

            }
          );

        }
      );

    }
  );

  const contenedor =
    $("#productos-recomendados");

  if (!contenedor) {

    console.error(
      "No se encontró #productos-recomendados."
    );

    return;
  }

  contenedor.innerHTML = "";

  if (todos.length === 0) {

    contenedor.innerHTML = `
      <div class="mensaje-vacio">
        No hay productos disponibles
        para recomendar.
      </div>
    `;

    return;
  }

  const seleccionados =
    [...todos]
      .sort(
        () =>
          Math.random() - 0.5
      )
      .slice(0, 6);

  seleccionados.forEach(
    (producto) => {

      contenedor.appendChild(
        crearTarjetaProducto(
          producto.nombre,
          producto.precio,
          producto.marca,
          producto.imagen
        )
      );

    }
  );
}

function actualizarCarrito() {

  const lista =
    $("#lista-carrito");

  lista.innerHTML = "";

  if (carrito.length === 0) {

    lista.innerHTML = `
      <div class="mensaje-vacio">
        Tu carrito está vacío.
      </div>
    `;

  } else {

    carrito.forEach(
      (item, indice) => {

        const elemento =
          document.createElement(
            "article"
          );

        elemento.className =
          "item-carrito";

        const subtotal =
          item.precio *
          item.cantidad;

        elemento.innerHTML = `
          <div class="item-carrito-info">

            <strong>
              ${escaparHTML(item.nombre)}
            </strong>

            <small>
              ${escaparHTML(item.marca)}
              ·
              $${formatearPrecio(item.precio)}
              c/u
            </small>

          </div>

          <div class="item-precio">
            $${formatearPrecio(subtotal)}
          </div>

          <div
            class="controles-carrito"
            aria-label="Cantidad de ${escaparHTML(item.nombre)}"
          >

            <button
              type="button"
              data-accion="menos"
              aria-label="Disminuir"
            >
              −
            </button>

            <span>
              ${item.cantidad}
            </span>

            <button
              type="button"
              data-accion="mas"
              aria-label="Aumentar"
            >
              +
            </button>

          </div>

          <button
            type="button"
            class="boton-eliminar"
            data-accion="eliminar"
          >
            Eliminar
          </button>
        `;

        elemento
          .querySelector(
            '[data-accion="menos"]'
          )
          .addEventListener(
            "click",
            () => {

              if (item.cantidad > 1) {
                item.cantidad--;
              }

              actualizarCarrito();

            }
          );

        elemento
          .querySelector(
            '[data-accion="mas"]'
          )
          .addEventListener(
            "click",
            () => {

              item.cantidad++;

              actualizarCarrito();

            }
          );

        elemento
          .querySelector(
            '[data-accion="eliminar"]'
          )
          .addEventListener(
            "click",
            () => {

              carrito.splice(
                indice,
                1
              );

              actualizarCarrito();

            }
          );

        lista.appendChild(
          elemento
        );

      }
    );
  }

  const cantidadTotal =
    carrito.reduce(
      (total, item) =>
        total + item.cantidad,
      0
    );

  const total =
    carrito.reduce(
      (suma, item) =>
        suma +
        item.precio *
        item.cantidad,
      0
    );

  $("#total").textContent =
    formatearPrecio(total);

  $("#cantidad-flotante")
    .textContent =
    cantidadTotal;

  $("#total-flotante")
    .textContent =
    formatearPrecio(total);
}

function abrirCarrito() {

  $("#carrito").scrollIntoView({
    behavior: "smooth",
    block: "start"
  });

}

function enviarPedidoWhatsApp(
  numero
) {

  if (carrito.length === 0) {

    alert(
      "Tu carrito está vacío. Añade al menos un producto antes de enviar el pedido."
    );

    return;
  }

  let mensaje =
    "Buen día, estoy interesado en realizar el siguiente pedido:\n\n";

  let total = 0;

  carrito.forEach(
    (item, indice) => {

      const subtotal =
        item.precio *
        item.cantidad;

      total += subtotal;

      mensaje +=
        `${indice + 1}. ${item.marca} - ${item.nombre}\n` +
        `Cantidad: ${item.cantidad}\n` +
        `Precio unitario: $${formatearPrecio(item.precio)}\n` +
        `Subtotal: $${formatearPrecio(subtotal)}\n\n`;

    }
  );

  mensaje +=
    `TOTAL: $${formatearPrecio(total)}\n\n` +
    "Quedo atento(a) a la confirmación del pedido. Muchas gracias.";

  const url =
    `https://wa.me/${numero}?text=${encodeURIComponent(mensaje)}`;

  window.open(
    url,
    "_blank",
    "noopener,noreferrer"
  );
}

document.addEventListener(
  "DOMContentLoaded",
  () => {

    document
      .querySelectorAll(
        ".categoria-card"
      )
      .forEach(
        (boton) => {

          boton.addEventListener(
            "click",
            () =>
              mostrarCategoria(
                boton.dataset.categoria
              )
          );

        }
      );

    const carritoFlotante =
      $("#carrito-flotante");

    if (carritoFlotante) {

      carritoFlotante.addEventListener(
        "click",
        abrirCarrito
      );

    }

    document
      .querySelectorAll(
        "[data-whatsapp]"
      )
      .forEach(
        (boton) => {

          boton.addEventListener(
            "click",
            () =>
              enviarPedidoWhatsApp(
                boton.dataset.whatsapp
              )
          );

        }
      );

    inicializarFiltros();

    mostrarRecomendaciones();

    actualizarCarrito();

  }
);